// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"blockchain":{"slug":"blockchain","cat":"basics","en":"Blockchain","contentLocale":"pt-BR","term":"Blockchain","aka":["cadeia de blocos"],"short":"Blockchain é um registro digital compartilhado, organizado em blocos encadeados, que milhares de computadores mantêm juntos e que praticamente não pode ser alterado depois de gravado.","body":["Pense na blockchain como um livro-caixa público. Cada bloco reúne um lote de transações e guarda uma impressão digital (hash) do bloco anterior. Se alguém tentar mudar um registro antigo, o hash não bate mais e toda a rede percebe a fraude.",["Quem decide qual bloco entra na cadeia é o mecanismo de consenso. O ",["Bitcoin","bitcoin"]," usa ",["prova de trabalho","proof-of-work"]," (",["mineração","mining"],"), enquanto o ",["Ethereum","ethereum"]," usa ",["prova de participação","proof-of-stake"],", com validadores que travam ETH como garantia. Não existe um banco central aprovando as operações: as regras estão no próprio protocolo."],["Para você, isso significa duas coisas práticas. Primeiro, qualquer transação pode ser conferida num ",["explorador de blocos","block-explorer"],". Segundo, uma transferência confirmada não tem estorno: se você enviar para o endereço errado, ninguém consegue desfazer. Por isso vale conferir rede e endereço antes de cada envio."]],"example":"Imagine que você saca 0,01 BTC da corretora para sua carteira. A transação entra na fila, um minerador a inclui num bloco e, cerca de 10 minutos depois, ela aparece com 1 confirmação. A cada novo bloco acima dela, o número de confirmações sobe. Muitas corretoras só creditam depósitos de BTC depois de algumas confirmações, porque cada bloco extra torna a reversão praticamente impossível.","mistakes":["Achar que blockchain e Bitcoin são a mesma coisa, quando o Bitcoin é só uma das muitas redes que usam essa tecnologia.","Acreditar que a blockchain é anônima, quando na verdade todas as transações ficam públicas e podem ser rastreadas.","Supor que dá para cancelar ou estornar uma transação confirmada, como num Pix enviado por engano ao banco."],"faq":[{"q":"Blockchain pode ser hackeada?","a":"Alterar o histórico de uma blockchain grande como a do Bitcoin exigiria controlar a maior parte do poder da rede, o que é extremamente caro. Os ataques mais comuns acontecem em corretoras, carteiras e contratos inteligentes, não na cadeia em si."},{"q":"Para que serve a blockchain além das criptomoedas?","a":"Ela também é usada para contratos inteligentes, tokens, registros de propriedade e rastreamento de cadeias de suprimento. Em todos os casos, a vantagem é ter um registro compartilhado que ninguém altera sozinho."}],"title":"O que é blockchain? Significado e como funciona","description":"Entenda o que é blockchain, como os blocos se encadeiam, o que é consenso e por que uma transação confirmada não tem estorno.","related":[["cryptocurrency","Criptomoeda","Criptomoeda é um ativo digital que funciona sobre uma blockchain, usa criptografia para proteger as transferências e não depende de um banco central para existir."],["proof-of-work","Prova de trabalho (PoW)","Prova de trabalho (PoW) é o mecanismo de consenso em que mineradores gastam poder computacional e energia para resolver um desafio matemático e ganhar o direito de adicionar o próximo bloco."],["proof-of-stake","Prova de participação (PoS)","Prova de participação (PoS) é o mecanismo de consenso em que validadores travam criptomoedas como garantia para confirmar blocos, ganhando recompensas e arriscando perder parte do valor se agirem mal."],["smart-contract","Contrato inteligente (smart contract)","Contrato inteligente é um programa publicado numa blockchain que executa automaticamente regras predefinidas, como trocar tokens ou liberar fundos, sem depender de um intermediário."],["block-explorer","Explorador de blocos (block explorer)","Um explorador de blocos é um site de busca que mostra os dados públicos de uma blockchain, permitindo consultar transações, endereços, blocos e saldos a partir de um hash ou de um endereço."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Onde estão minhas moedas? Corretora vs carteira"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"trading-volume":{"slug":"trading-volume","cat":"trading","en":"Trading volume","contentLocale":"pt-BR","term":"Volume de negociação","aka":["volume","volume 24h","trading volume"],"short":"Volume de negociação é a quantidade total de um ativo comprada e vendida em um período, geralmente as últimas 24 horas, medida em moedas ou em dólares.","body":[["Cada negócio fechado entre um comprador e um vendedor entra no volume. Uma compra de 1 ",["BTC","bitcoin"]," conta como 1 BTC de volume, não 2, porque comprador e vendedor são os dois lados da mesma operação. Sites agregadores somam o volume de várias corretoras para mostrar o volume global de uma moeda."],"Traders usam o volume para medir interesse e confirmar movimentos. Uma alta com volume crescente costuma indicar participação ampla. Uma alta com volume fraco mostra que pouca gente está negociando naquele preço. Nos gráficos de candles, o volume aparece como barras abaixo de cada vela.",["Fique atento: volume de futuros costuma ser bem maior que o de spot, porque é calculado sobre o valor nocional ",["alavancado","leverage"],". E nem todo volume é real. Corretoras pequenas e tokens obscuros podem ter volume inflado por ",["wash trading","wash-trading"],", quando a mesma pessoa compra e vende para si mesma."]],"example":["Suponha que uma moeda tenha ",["valor de mercado","market-capitalization"]," de 500 milhões de dólares e volume de 24 horas de 25 milhões. A razão volume/valor de mercado é de 5%, um nível comum. Se outra moeda com valor de mercado de 20 milhões mostra volume de 40 milhões no dia, ou seja, 200%, vale investigar: pode ser uma notícia forte ou volume artificial concentrado em uma única corretora."],"mistakes":["Comparar volume de futuros com volume de spot como se fossem a mesma coisa.","Achar que volume alto sempre significa alta de preço, quando ele também cresce em quedas fortes.","Não verificar em quais corretoras o volume está concentrado."],"faq":[{"q":"O que significa volume 24h em cripto?","a":"É o valor total negociado de uma moeda nas últimas 24 horas, em uma corretora ou somando várias. Ele mostra quanto aquele mercado está ativo."},{"q":"Volume alto é bom ou ruim?","a":"Volume alto e real geralmente traz mais liquidez e spreads menores. Mas ele precisa ser analisado junto com o preço e a origem, porque pode ser inflado."}],"title":"O que é volume de negociação em cripto?","description":"Entenda o que é volume de negociação, como ler o volume 24h, a diferença entre spot e futuros e como identificar volume inflado.","related":[["liquidity","Liquidez","Liquidez é a facilidade de comprar ou vender um ativo rapidamente, em quantidade relevante, sem mexer muito no preço."],["market-capitalization","Capitalização de mercado (market cap)","Capitalização de mercado é o valor total de uma criptomoeda, calculado multiplicando o preço atual pela oferta circulante de moedas."],["open-interest","Contratos em aberto (open interest)","Contratos em aberto (open interest) é o total de contratos futuros ou de opções que estão abertos e ainda não foram fechados ou liquidados em um determinado momento."],["wash-trading","Wash trading","Wash trading é a prática de comprar e vender o mesmo ativo para si mesmo, ou entre contas combinadas, para criar volume falso e passar a impressão de um mercado ativo."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"position-sizing":{"slug":"position-sizing","cat":"trading","en":"Position sizing","contentLocale":"pt-BR","term":"Dimensionamento de posição","aka":["position sizing","tamanho da posição","gestão de risco por operação"],"short":"Dimensionamento de posição (position sizing) é decidir quanto colocar em cada operação com base em quanto você aceita perder se o stop loss for atingido.","body":[["A ideia central é começar pelo risco, não pelo lucro. Primeiro você define quanto do seu capital aceita perder em uma operação, muitos traders usam entre 0,5% e 2%. Depois mede a distância entre a entrada e o ",["stop loss","stop-loss"],". O tamanho da posição é o risco em dinheiro dividido por essa distância."],"Assim, uma operação com stop curto permite posição maior, e uma com stop largo exige posição menor, mas a perda máxima planejada é sempre a mesma. Isso evita que uma única operação ruim apague semanas de ganhos.",["A ",["alavancagem","leverage"]," não muda esse cálculo, só muda quanta margem você precisa depositar. O que muda o risco é o tamanho da posição e onde está o stop. Em futuros, confira também se o ",["preço de liquidação","liquidation-price"]," fica bem além do seu stop, para o stop agir antes da ",["liquidação","liquidation"],"."]],"example":["Você tem 5.000 ",["USDT","usdt"]," e decide arriscar 1% por operação, ou seja, 50 USDT. Quer comprar ",["ETH","ethereum"]," a 3.000 com stop em 2.900, uma distância de 100 USDT. O tamanho da posição é 50 dividido por 100, que dá 0,5 ETH, ou 1.500 USDT de valor. Se o stop for atingido, você perde 50 USDT, mais as taxas, não importa se usou alavancagem de 2x ou 5x para abrir a posição."],"mistakes":["Definir o tamanho pela alavancagem ou pelo saldo disponível em vez de pela distância até o stop.","Aumentar a posição depois de perdas para recuperar rápido.","Esquecer de incluir taxas e slippage no risco planejado."],"faq":[{"q":"Quanto arriscar por operação?","a":"Muitos traders limitam o risco a algo entre 0,5% e 2% do capital por operação. O número exato depende da sua estratégia e da sua tolerância, mas deve ser definido antes de entrar."},{"q":"Alavancagem aumenta o risco da operação?","a":"O risco real vem do tamanho da posição e da distância do stop. A alavancagem facilita abrir posições grandes com pouca margem, e também aproxima o preço de liquidação."}],"title":"O que é position sizing? Como calcular o tamanho","description":"Aprenda a calcular o tamanho da posição a partir do risco por operação e do stop loss, com exemplo prático em cripto.","related":[["risk-reward-ratio","Relação risco-retorno","Relação risco-retorno é a comparação entre quanto você pode perder até o stop loss e quanto pode ganhar até o alvo de uma operação, como 1 para 3."],["stop-loss","Stop loss","Stop loss é uma ordem programada para vender, ou fechar uma posição, automaticamente quando o preço atinge um nível definido, limitando a perda de uma operação."],["leverage","Alavancagem","Alavancagem é o uso de margem para abrir uma posição maior do que o seu capital, multiplicando tanto os ganhos quanto as perdas em relação ao valor depositado."],["liquidation","Liquidação","Liquidação é o fechamento forçado de uma posição alavancada pela corretora quando a margem restante cai abaixo da margem de manutenção, para evitar que as perdas ultrapassem a garantia."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"Decida quanto você pode perder antes de decidir quanto comprar"},"coin":null,"tool":null,"cta":false},"funding-rate":{"slug":"funding-rate","cat":"derivatives","en":"Funding rate","contentLocale":"pt-BR","term":"Taxa de financiamento (funding rate)","aka":["funding rate","funding","taxa de funding"],"short":"Taxa de financiamento (funding rate) é um pagamento periódico entre traders comprados e vendidos em futuros perpétuos, usado para manter o preço do contrato próximo do preço à vista.","body":[["Quando o ",["perpétuo","perpetual-futures"]," negocia acima do índice à vista, a taxa tende a ser positiva: quem está ",["comprado","long-and-short"]," paga quem está vendido. Isso desestimula novos longs e atrai shorts, puxando o preço de volta. Quando o perpétuo está abaixo do índice, a taxa fica negativa e os vendidos pagam os comprados."],["O valor pago é a taxa multiplicada pelo valor nocional da posição, não pela margem. O pagamento é feito diretamente entre traders, a corretora não fica com ele. Muitas corretoras cobram a cada 8 horas, mas há pares e plataformas com intervalos de 1, 2 ou 4 horas, e algumas ajustam o intervalo em momentos de ",["volatilidade","volatility"],". Você só paga ou recebe se tiver posição aberta no horário da cobrança."],"Funding muito positivo indica que há muitos comprados alavancados. Muitos traders observam esse dado como termômetro do sentimento, mas ele sozinho não prevê a direção do preço."],"example":["Suponha um long de 0,5 ",["BTC","bitcoin"]," a 60.000 ",["USDT","usdt"],", valor nocional de 30.000 USDT, com funding de 0,03% a cada 8 horas. A cada cobrança você paga 9 USDT. Em um dia, com 3 cobranças, são 27 USDT. Em 30 dias com a taxa constante, 810 USDT. Se você usou 3.000 USDT de margem, o funding sozinho consumiria 27% dela."],"mistakes":["Calcular o funding sobre a margem em vez do valor nocional da posição.","Abrir posição minutos antes da cobrança sem checar a taxa e o horário.","Supor que todas as corretoras usam intervalo de 8 horas."],"faq":[{"q":"Funding rate negativo é sinal de alta?","a":"Funding negativo mostra que há mais pressão vendedora nos perpétuos e que os shorts estão pagando. Às vezes isso antecede um short squeeze, mas não é um sinal garantido."},{"q":"A corretora fica com a taxa de financiamento?","a":"Em geral não. O funding é transferido entre os traders comprados e vendidos. A corretora ganha com as taxas de negociação."},{"q":"Pago funding se fechar antes do horário?","a":"Não. O funding só é aplicado a posições abertas no momento exato da cobrança."}],"title":"O que é funding rate (taxa de financiamento)?","description":"Entenda o que é a taxa de financiamento dos futuros perpétuos, quem paga quem, como calcular o custo e por que os intervalos variam.","related":[["perpetual-futures","Futuros perpétuos","Futuros perpétuos são contratos futuros sem data de vencimento, que acompanham o preço à vista do ativo por meio de uma taxa de financiamento paga periodicamente entre comprados e vendidos."],["funding-rate-arbitrage","Arbitragem de taxa de financiamento","Arbitragem de taxa de financiamento é a estratégia de comprar um ativo no spot e abrir um short do mesmo tamanho no perpétuo, ficando neutro ao preço e recebendo o funding quando ele é positivo."],["mark-price","Preço de marcação","Preço de marcação é o preço de referência que a corretora usa para calcular lucro não realizado e liquidações em futuros, baseado no preço índice e não só no último negócio."],["index-price","Preço índice","Preço índice é a média ponderada do preço à vista de um ativo em várias corretoras, usada como referência para o preço de marcação e a taxa de financiamento."],["open-interest","Contratos em aberto (open interest)","Contratos em aberto (open interest) é o total de contratos futuros ou de opções que estão abertos e ainda não foram fechados ou liquidados em um determinado momento."]],"lesson":{"id":"E24","slug":"funding-fees-final","ep":24,"title":"Preço estável, saldo em queda? Conclua o último nível com os custos em mente"},"coin":null,"tool":"/funding-rates","cta":true},"defi":{"slug":"defi","cat":"defi","en":"DeFi (decentralized finance)","contentLocale":"pt-BR","term":"DeFi (finanças descentralizadas)","aka":["finanças descentralizadas","decentralized finance"],"short":"DeFi (finanças descentralizadas) é o conjunto de serviços financeiros, como trocas, empréstimos e rendimento, oferecidos por contratos inteligentes em blockchains, sem um banco ou corretora intermediando.","body":[["Em vez de abrir conta e passar por cadastro, você conecta uma ",["carteira não custodial","non-custodial-wallet"]," a um aplicativo e interage diretamente com contratos. Exemplos conhecidos são Uniswap para trocas, Aave para empréstimos e Lido para ",["staking líquido","liquid-staking"],". A maior parte do DeFi roda em ",["Ethereum","ethereum"]," e redes compatíveis, mas também há ecossistemas em Solana e outras redes."],["A vantagem é que tudo fica aberto e verificável: qualquer um pode usar, o código costuma ser público e os saldos estão na ",["blockchain","blockchain"],". Você mantém a custódia dos ativos e pode combinar protocolos entre si."],["Os riscos são diferentes dos de uma corretora: bugs em contratos, ataques a oráculos, aprovações maliciosas, ",["depeg","depeg"]," de ",["stablecoins","stablecoin"]," e taxas de gás altas em momentos de congestionamento. Não existe suporte para reverter um erro. Regras e tributação também variam por país, inclusive no Brasil."]],"example":"Imagine que você tenha 1 ETH, cotado a 3.000 USDC no exemplo. Você deposita o ETH em um protocolo de empréstimo e pega 1.200 USDC emprestados, 40% do valor da garantia. Depois troca 600 USDC por outro token em uma DEX. Tudo acontece em contratos, sem cadastro, pagando taxas de gás a cada etapa. Se o ETH cair para 1.600 USDC, sua dívida de 1.200 passa a representar 75% da garantia e pode disparar liquidação, dependendo das regras do protocolo.","mistakes":["Usar um protocolo DeFi só pelo rendimento alto, sem entender de onde ele vem.","Esquecer que cada etapa custa taxa de gás, o que pode tornar operações pequenas inviáveis em Ethereum.","Achar que DeFi tem suporte para recuperar fundos enviados ou aprovados por engano."],"faq":[{"q":"DeFi é seguro?","a":"Depende do protocolo, da auditoria do código, do tempo de funcionamento e de como você usa. Mesmo protocolos grandes já sofreram falhas, então é comum distribuir o risco e não deixar tudo em um só lugar."},{"q":"Preciso de corretora para usar DeFi?","a":"Não para usar os protocolos, mas muita gente compra cripto em uma corretora e depois envia para uma carteira não custodial para acessar o DeFi."}],"title":"O que é DeFi (finanças descentralizadas)? Guia","description":"Entenda o que é DeFi, como funcionam trocas e empréstimos em contratos inteligentes e quais riscos existem fora das corretoras.","related":[["dex","Corretora descentralizada (DEX)","Uma corretora descentralizada (DEX) é uma plataforma onde você troca criptomoedas diretamente da sua carteira por meio de contratos inteligentes, sem entregar a custódia a uma empresa."],["smart-contract","Contrato inteligente (smart contract)","Contrato inteligente é um programa publicado numa blockchain que executa automaticamente regras predefinidas, como trocar tokens ou liberar fundos, sem depender de um intermediário."],["total-value-locked","Valor total bloqueado (TVL)","O valor total bloqueado (TVL) é a soma, em dólares, de todos os ativos depositados nos contratos de um protocolo DeFi ou de uma blockchain em determinado momento."],["defi-lending","Empréstimo DeFi (DeFi lending)","Empréstimo DeFi é o uso de protocolos em contratos inteligentes, como Aave e Compound, para emprestar cripto e receber juros ou tomar empréstimos deixando outra cripto como garantia."],["liquidity-pool","Pool de liquidez (liquidity pool)","Um pool de liquidez é um conjunto de tokens travados em um contrato inteligente que permite trocas em uma DEX, em que os depositantes, chamados provedores de liquidez, recebem parte das taxas."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"cross-chain-bridge":{"slug":"cross-chain-bridge","cat":"defi","en":"Cross-chain bridge","contentLocale":"pt-BR","term":"Ponte entre blockchains (cross-chain bridge)","aka":["bridge","ponte cross-chain","cross-chain bridge","ponte"],"short":"Uma ponte entre blockchains (bridge) é um protocolo que permite mover tokens ou mensagens de uma rede para outra, por exemplo do Ethereum para uma rede de camada 2 ou para Solana.","body":[["Blockchains não conversam entre si nativamente. O modelo mais comum de ponte é travar e cunhar: você trava o token em um contrato na rede de origem e a ponte cunha uma versão equivalente na rede de destino. Na volta, a versão é queimada e o original é liberado. Outros modelos usam pools de ",["liquidez","liquidity"]," nos dois lados ou emissões nativas do próprio emissor, como o protocolo da Circle para ",["USDC","usdc"],"."],["As pontes oficiais das redes de ",["camada 2","layer-2"]," tendem a ser mais lentas na saída, às vezes com espera de dias em rollups otimistas, enquanto pontes de terceiros são mais rápidas e cobram taxa. Corretoras centralizadas também funcionam como ponte prática: você deposita em uma rede e saca em outra."],"Pontes concentram muito valor em contratos e chaves, e por isso estiveram entre os maiores ataques do mercado, como o da ponte Ronin em 2022. Use pontes conhecidas, confira o token que chega no destino e faça um teste pequeno primeiro."],"example":["Você quer levar 1.000 USDC do ",["Ethereum","ethereum"]," para uma rede de camada 2. Pela ponte oficial, paga cerca de 6 USDC em gás no Ethereum e recebe 1.000 USDC em alguns minutos. Por uma ponte de terceiros, paga uma taxa de 0,1%, ou 1 USDC, mais o gás. Outra opção é sacar de uma corretora direto na camada 2, se ela suportar a rede. Em todos os casos, confira se chegou o USDC nativo ou uma versão bridged."],"mistakes":["Usar uma ponte desconhecida só porque cobra menos, sem checar histórico e auditorias.","Não verificar se o token recebido é a versão nativa ou uma versão bridged com outro contrato.","Esquecer de ter um pouco do token de gás da rede de destino para movimentar os fundos depois."],"faq":[{"q":"Pontes cross-chain são seguras?","a":"O risco varia muito. Pontes guardam grandes valores e já sofreram ataques bilionários, então prefira as oficiais ou as mais estabelecidas e evite deixar fundos parados em versões bridged sem necessidade."},{"q":"Usar corretora é uma alternativa à ponte?","a":"Sim, quando a corretora aceita depósito em uma rede e saque em outra para o mesmo ativo. Você troca o risco da ponte pelo risco de custódia temporária e paga a taxa de saque."}],"title":"O que é bridge (ponte entre blockchains)?","description":"Entenda o que é uma ponte cross-chain, como funciona o modelo travar e cunhar e quais cuidados tomar ao mover tokens entre redes.","related":[["wrapped-token","Token embrulhado (wrapped token)","Um token embrulhado (wrapped token) é um token que representa outro ativo na proporção de 1 para 1, permitindo usar esse ativo em uma rede ou padrão em que ele não existe de forma nativa."],["layer-2","Camada 2 (Layer 2, L2)","Camada 2 (L2) é uma rede construída sobre uma blockchain base, como o Ethereum, que processa transações fora dela de forma mais rápida e barata e depois registra os resultados na camada 1."],["blockchain-network","Rede de depósito (escolha da rede)","A rede de depósito é a blockchain específica, como Ethereum (ERC20), Tron (TRC20) ou Solana, pela qual uma criptomoeda é transferida, e precisa ser a mesma no envio e no recebimento para o dinheiro chegar."],["smart-contract","Contrato inteligente (smart contract)","Contrato inteligente é um programa publicado numa blockchain que executa automaticamente regras predefinidas, como trocar tokens ou liberar fundos, sem depender de um intermediário."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Antes de transferir: não chute nenhum destes pontos"},"coin":null,"tool":null,"cta":false},"stablecoin":{"slug":"stablecoin","cat":"stablecoins","en":"Stablecoin","contentLocale":"pt-BR","term":"Stablecoin (moeda estável)","aka":["moeda estável","stablecoins","criptodólar","dólar digital"],"short":"Uma stablecoin é uma criptomoeda projetada para manter um valor estável, geralmente 1 dólar americano, por meio de reservas em moeda tradicional, garantia em cripto ou mecanismos de mercado.","body":[["Os principais modelos são três. Stablecoins lastreadas em moeda fiduciária, como ",["USDT","usdt"]," da Tether e ",["USDC","usdc"]," da Circle, mantêm reservas em dinheiro e títulos de curto prazo. Stablecoins lastreadas em cripto, como DAI e USDS, são emitidas contra garantias em cripto acima do valor emitido. Dólares sintéticos, como o USDe, usam estratégias com derivativos para manter o valor."],["No Brasil, muita gente usa stablecoins como forma de ter exposição ao dólar, comprando em corretoras com depósito via Pix ou por ",["P2P","p2p-trading"],", e para mover dinheiro entre corretoras e redes. Também são a principal moeda de margem em futuros."],["Estável não quer dizer sem risco. Uma stablecoin pode perder a paridade, o chamado ",["depeg","depeg"],", por problemas nas reservas, falhas no mecanismo ou corrida de resgates. A USDC, por exemplo, ficou abaixo de 0,90 dólar por pouco tempo em março de 2023, quando parte das reservas estava no Silicon Valley Bank. Regras como as da ",["MiCA","mica"],", na União Europeia, e as normas de cada país mudam o que é permitido."]],"example":"Suponha que você deposite R$ 5.500 via Pix em uma corretora e compre USDT a R$ 5,50, ficando com 1.000 USDT. Meses depois, o dólar sobe para R$ 6,00 e você vende os 1.000 USDT, recebendo R$ 6.000, sem contar taxas. O ganho de R$ 500 veio da variação do dólar contra o real, não de rendimento da stablecoin. Se o dólar caísse para R$ 5,00, os mesmos 1.000 USDT valeriam R$ 5.000.","mistakes":["Achar que toda stablecoin tem o mesmo nível de risco, independentemente de quem emite e de como é lastreada.","Esquecer que, para quem pensa em reais, a stablecoin em dólar continua sujeita ao câmbio.","Enviar uma stablecoin pela rede errada porque ela existe em várias blockchains."],"faq":[{"q":"Stablecoin é a mesma coisa que dólar?","a":"Não. Ela busca acompanhar o dólar, mas é um token emitido por uma empresa ou protocolo, com riscos de reservas, custódia e regulação próprios."},{"q":"Qual a diferença entre USDT e USDC?","a":"As duas buscam valer 1 dólar e são lastreadas em reservas, mas são emitidas por empresas diferentes, Tether e Circle, com políticas de reservas, transparência e regulação distintas."}],"title":"O que é stablecoin? Tipos, usos e riscos","description":"Saiba o que é uma stablecoin, como funcionam os tipos lastreados em dólar, em cripto e sintéticos e o que é perder a paridade.","related":[["usdt","USDT (Tether)","USDT (Tether) é a maior stablecoin do mercado, emitida pela empresa Tether, que busca manter o valor de 1 dólar americano por token com base em reservas compostas principalmente por títulos do Tesouro dos EUA e outros ativos."],["usdc","USDC (USD Coin)","USDC (USD Coin) é uma stablecoin emitida pela Circle que busca valer 1 dólar americano por token, lastreada em reservas de dinheiro e títulos de curto prazo do Tesouro dos EUA."],["depeg","Depeg (perda de paridade)","Depeg é quando uma stablecoin ou outro token atrelado a um ativo se afasta do preço que deveria acompanhar, como uma moeda de 1 dólar sendo negociada a 0,97 ou a 1,03 dólar."],["crypto-backed-stablecoin","Stablecoin lastreada em cripto","Uma stablecoin lastreada em cripto é uma moeda estável criada a partir de garantias em criptomoedas depositadas em contratos inteligentes, normalmente com mais valor em garantia do que em moedas emitidas."],["synthetic-dollar","Dólar sintético (stablecoin delta neutra)","Um dólar sintético é um token que busca valer 1 dólar combinando uma posição comprada em cripto com uma posição vendida do mesmo tamanho em futuros perpétuos, de modo que as variações de preço se anulem."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT é dólar? Por que ele aparece em todo lugar ao comprar cripto?"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":false}});
